void* av_buffer_pool_init(size_t size) {
    printf("[ALLOC] Requested: %zu bytes\n", size);
    return malloc(size);
}

void vulnerable_pool_init(H264Context* h) {
    // Crafted dimensions from a malicious H.264 stream
    h->mb_stride = 50000;
    h->mb_height = 50000;

    // Line 145: h->mb_stride * (h->mb_height + 1)
    // Operands are 32-bit signed int. Multiplication exceeds INT_MAX.
