    int raw_size = h->mb_stride * (h->mb_height + 1);

    // Implicit cast to size_t when passed to allocation function.
    // In practice, truncation to 32-bit unsigned before promotion can wrap
    // the negative overflow to a small positive number, causing undersized allocation.
    void* pool = av_buffer_pool_init(raw_size);

    printf("[OVERFLOW] Signed result: %d\n", raw_size);
    printf("[CAST] size_t result: %zu\n", (size_t)raw_size);

    if (pool) free(pool);
}

