#include <stdint.h>

// Minimal PoC demonstrating signed integer overflow in allocation size calculation
void alloc_scratch_buffers(int mb_width) {
    // Vulnerable line: uses 32-bit signed integer arithmetic for multiplication
    // Multiplier constant: 16 * 3 * sizeof(uint8_t) * 2 = 96
    // When mb_width > ~22,369,621, the product exceeds INT32_MAX and wraps around
    int raw_calc = mb_width * 16 * 3 * sizeof(uint8_t) * 2;

    // The overflowed signed value is cast to size_t (unsigned 64-bit on modern systems)
    // This preserves the small/negative wrapped value instead of detecting the overflow
    size_t alloc_size = (size_t)raw_calc;

    printf("[INFO] mb_width: %d\n", mb_width);
    printf("[INFO] Raw signed calculation: %d\n", raw_calc);
    printf("[INFO] Cast to size_t: %zu\n", alloc_size);

    // Allocate based on the undersized size (simulates av_fast_mallocz)
    uint8_t *top_borders[2];
    for (int i = 0; i < 2; i++) {
        top_borders[i] = malloc(alloc_size);
        if (!top_borders[i]) {
            fprintf(stderr, "[ERROR] Allocation failed\n");
            return;
        }
    }

    // Educational note: In the real H.264 decoder, subsequent edge emulation
    // or inter-prediction writes would exceed alloc_size, causing a heap buffer overflow.
    // Actual out-of-bounds write omitted to prevent memory corruption in this PoC.
    printf("[INFO] Allocated %zu bytes per border. Safe for demonstration.\n", alloc_size);

    // Cleanup
    for (int i = 0; i < 2; i++) free(top_borders[i]);
}

int main(void) {
    // Value chosen to trigger the 32-bit signed integer overflow
    // 25,000,000 * 96 = 2,400,000,000 > INT32_MAX (2,147,483,647)
    int trigger_mb_width = 25000000;
    printf("=== Integer Overflow Allocation PoC ===\n");
    alloc_scratch_buffers(trigger_mb_width);
    return 0;
}

#include <stdio.h>
#include <string.h>

/* Simulates the vulnerable MOV demuxer string parsing function */
void mov_read_mac_string_vulnerable(char *dst, size_t dstlen, const char *src, size_t src_len) {
    char *p = dst;
    /* VULNERABILITY: dstlen is derived from untrusted external input (e.g., atom length)
       without verifying it against the actual allocated size of dst. */
    char *end = dst + dstlen - 1;

    printf("[DEBUG] dst buffer size: %zu\n", dstlen);
    printf("[DEBUG] Computed 'end' pointer offset: %ld\n", (long)(end - dst));

    /* Loop processes source bytes. The condition 'p < end' relies on the poisoned 'end'. */
    for (size_t i = 0; i < src_len && p < end; i++) {
        unsigned char c = src[i];
        /* Conceptual PUT_UTF8 macro behavior: writes byte to buffer.
           In the real code, PUT_UTF8 performs per-byte bounds checks against 'end',
           but since 'end' is already miscalculated, these checks are ineffective. */
        *p++ = c;
        printf("[DEBUG] Wrote byte 0x%02X at offset %ld (p < end: %s)\n", c, (long)(p - dst - 1), p < end ? "true" : "false");
    }

    printf("[OVERFLOW DEMO] Intended buffer size was %zu, but loop condition allowed writes up to offset %ld.\n", dstlen, (long)(p - dst));
}

int main() {
    /* Allocate a small, fixed-size buffer (simulating stack/heap allocation) */
    char dst[16];
    memset(dst, 0, sizeof(dst));

    /* Simulate untrusted input: attacker-controlled atom length from a crafted MOV file */
    size_t untrusted_dstlen = 1024; // Much larger than actual buffer size
    const char *src = "Hello, malicious MOV atom!";
    size_t src_len = strlen(src);

    printf("=== Vulnerable MOV String Parser PoC ===\n");
    printf("Actual buffer size: %zu\n", sizeof(dst));
    printf("Untrusted length (from file): %zu\n\n", untrusted_dstlen);

    /* Execute vulnerable function */
    mov_read_mac_string_vulnerable(dst, untrusted_dstlen, src, src_len);

    return 0;
}

