/*
 * Conceptual PoC demonstrating the integer overflow -> heap buffer overflow
 * vulnerability in H.264 macroblock dimension calculations.
 */
void demonstrate_vulnerability() {
    // Malicious macroblock dimensions crafted to trigger 32-bit signed overflow
    int32_t mb_width = 100000;
    int32_t mb_height = 100000;
    int32_t b4_stride = 4;

    // EXPECTED: 100000 * 100000 * 4 = 40,000,000,000 bytes (~38 GB)
    // VULNERABLE: Calculation uses 32-bit signed int arithmetic
    // The product exceeds INT_MAX (2,147,483,647) and wraps around
    int32_t overflowed_size = mb_width * mb_height * b4_stride;

    printf("[+] Expected allocation size: %lld bytes\n", (long long)mb_width * mb_height * b4_stride);
    printf("[+] Actual 32-bit calculation: %d bytes\n", overflowed_size);

    // EXPLOIT MECHANISM:
    // 1. The 32-bit signed multiplication overflows, wrapping to a small positive value
    //    (or negative, depending on exact inputs).
    // 2. This value is implicitly cast to size_t (unsigned 64-bit) for av_buffer_pool_init.
    // 3. If the wrapped value is small, av_buffer_pool_init allocates a severely undersized heap buffer.
    // 4. During slice decoding, motion vector writes use the true (large) macroblock coordinates,
    //    causing writes far beyond the allocated buffer bounds -> heap buffer overflow.
    size_t alloc_size = (size_t)overflowed_size;

    printf("[+] Cast to size_t for allocation: %zu bytes\n", alloc_size);
    printf("[!] VULNERABILITY: Undersized pool allocated due to 32-bit signed overflow.\n");
    printf("[!] Subsequent motion vector writes will overflow heap memory.\n");
}

int main() {
    demonstrate_vulnerability();
    return 0;
}
